// webForCore's tests (MIT), #142. LINQ to SQL's Strings and Error classes are generated by tools/linq/generate.cs, since
// referencesource doesn't publish .NET Framework's. These tests read FrameworkData/System.Data.Linq.json, the data read
// from .NET Framework 4.8's System.Data.Linq.dll, and check every generated member against it, without the generator:
// each error is an exception of .NET Framework's type, made with the same constructor and arguments, so its message is
// .NET Framework's (for an ArgumentNullException or ObjectDisposedException, the message .NET builds around them); each
// string is .NET Framework's resource, formatted as .NET Framework's SR.GetString formats it.

using System.Collections.Generic;
using System.Data.Linq.Mapping;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Resources;
using System.Text.Json.Nodes;
using Xunit;

namespace System.Data.Linq.Tests
{
    public class ErrorTests
    {
        private static readonly JsonObject Data = JsonNode.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "FrameworkData", "System.Data.Linq.json"))).AsObject();

        // Where the exception types of the data are: .NET's System.Private.CoreLib, System.Transactions and System.Xml.
        private static readonly Assembly[] ExceptionAssemblies =
        [
            typeof(object).Assembly,
            typeof(Transactions.TransactionPromotionException).Assembly,
            typeof(Xml.Schema.XmlSchemaException).Assembly,
        ];

        public static IEnumerable<object[]> Cases() => GeneratedCases.All.Select(c => new object[] { c.Class, c.Member });

        // The data's classes, members and resources, as .NET Framework has them.
        private static IEnumerable<JsonObject> Classes => Data["classes"].AsArray().Select(c => c.AsObject());

        private static JsonObject Member(string className, string member) =>
            Classes.Single(c => (string)c["type"] == className)["members"].AsArray().Select(m => m.AsObject()).Single(m => (string)m["name"] == member);

        private static string Resource(string baseName, string name) =>
            (string)Data["resources"].AsArray().Single(r => (string)r["name"] == baseName + ".resources")["strings"][name];

        [Fact]
        public void EveryMemberOfFrameworksStringsAndErrorClassesIsGenerated()
        {
            var framework = Classes
                .Where(c => ((string)c["type"]).EndsWith(".Strings") || ((string)c["type"]).EndsWith(".Error"))
                .SelectMany(c => c["members"].AsArray().Where(m => m["value"] != null).Select(m => $"{c["type"]}.{m["name"]}"))
                .Order().ToList();
            var generated = GeneratedCases.All.Select(c => $"{c.Class}.{c.Member}").Order().ToList();

            Assert.Equal(framework, generated);
            Assert.Equal(70 + 52 + 158, framework.Count(m => m.Contains(".Strings.")));
            Assert.Equal(66 + 55 + 152, framework.Count(m => m.Contains(".Error.")));
        }

        // The one member the data couldn't read is referencesource's own code (SqlClient/Error.cs), not generated.
        [Fact]
        public void ExpressionNotSupportedForSqlServerVersionIsReferencesources()
        {
            var notRead = Classes.SelectMany(c => c["members"]?.AsArray() ?? []).Where(m => m["notRead"] != null).Select(m => (string)m["name"]);
            Assert.Equal(["ExpressionNotSupportedForSqlServerVersion"], notRead);

            var reasons = new Collections.ObjectModel.Collection<string> { "first", "second" };
            Exception error = SqlClient.Error.ExpressionNotSupportedForSqlServerVersion(reasons);

            Assert.IsType<NotSupportedException>(error);
            Assert.Equal(Resource("System.Data.Linq.SqlClient", "CannotTranslateExpressionToSql") + "first" + Environment.NewLine + "second" + Environment.NewLine, error.Message);
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void IsFrameworks(string className, string member)
        {
            object actual = GeneratedCases.All.Single(c => c.Class == className && c.Member == member).Call();
            JsonObject data = Member(className, member);
            var arguments = data["parameters"].AsArray().ToDictionary(p => (string)p["name"], p => (object)$"<{p["name"]}>");

            object expected = Evaluate(data["value"], NamespaceOf(className), arguments);

            if (expected is Exception expectedException)
            {
                var exception = Assert.IsAssignableFrom<Exception>(actual);
                Assert.Equal(expectedException.GetType(), exception.GetType());
                Assert.Equal(expectedException.Message, exception.Message);
                Assert.Null(exception.InnerException);
                if (expectedException is ArgumentException argument)
                    Assert.Equal(argument.ParamName, ((ArgumentException)exception).ParamName);
            }
            else
            {
                Assert.Equal(expected, actual);
            }
        }

        // The assembly's resources are .NET Framework's: the same base names, string names and strings.
        [Fact]
        public void ResourcesAreFrameworks()
        {
            Assembly linq = typeof(DataContext).Assembly;
            var resources = Data["resources"].AsArray();
            Assert.Equal(resources.Select(r => (string)r["name"]).Order(), linq.GetManifestResourceNames().Order());
            foreach (var resource in resources)
            {
                string baseName = ((string)resource["name"])[..^".resources".Length];
                var manager = new ResourceManager(baseName, linq);
                var strings = resource["strings"].AsObject();
                foreach (var (name, value) in strings)
                    Assert.Equal((string)value, manager.GetString(name, CultureInfo.InvariantCulture));
                using var set = manager.GetResourceSet(CultureInfo.InvariantCulture, true, false);
                Assert.Equal(strings.Count, set.Cast<Collections.DictionaryEntry>().Count());
            }
        }

        // As .NET Framework's SR.GetString: a string argument longer than 1,024 characters is cut to 1,021 and "...".
        [Fact]
        public void LongArgumentsAreCut()
        {
            string longName = new string('x', 2000);

            string message = Strings.CouldNotConvert(longName, "B");

            Assert.Equal(string.Format(CultureInfo.CurrentCulture, Resource("System.Data.Linq", "CouldNotConvert"), new string('x', 1021) + "...", "B"), message);
            Assert.Equal(Strings.CouldNotConvert(new string('x', 1024), "B"), string.Format(CultureInfo.CurrentCulture, Resource("System.Data.Linq", "CouldNotConvert"), new string('x', 1024), "B"));
        }

        // Errors through LINQ to SQL's public API, as an application sees them.
        [Fact]
        public void DisposedDataContextThrowsFrameworksObjectDisposedException()
        {
            var context = new DataContext("Server=127.0.0.1;Database=None", new AttributeMappingSource());
            context.Dispose();

            var error = Assert.Throws<ObjectDisposedException>(() => context.GetTable<Thing>());

            // .NET Framework passes the message as the object name.
            Assert.Equal("DataContext accessed after Dispose.", error.ObjectName);
            Assert.Equal(new ObjectDisposedException("DataContext accessed after Dispose.").Message, error.Message);
        }

        [Fact]
        public void EntitySetErrorsAreFrameworks()
        {
            var set = new EntitySet<Thing>();
            set.Add(new Thing());

            var error = Assert.Throws<InvalidOperationException>(() => set.SetSource([new Thing()]));

            Assert.Equal("The EntitySet is already loaded and the source cannot be changed.", error.Message);
        }

        [Fact]
        public void MappingErrorsAreFrameworks()
        {
            var model = new AttributeMappingSource().GetModel(typeof(DataContext));

            var error = Assert.Throws<InvalidOperationException>(() => model.GetMetaType(typeof(TwoKeys)).IdentityMembers.ToList());

            Assert.Equal(string.Format(CultureInfo.CurrentCulture, Resource("System.Data.Linq.Mapping", "TwoMembersMarkedAsRowVersion"), typeof(TwoKeys).GetProperty("B"), typeof(TwoKeys).GetProperty("A")), error.Message);
        }

        // Evaluates a value of the data: a constructor, a call of Strings or SR, a parameter or a constant.
        private static object Evaluate(JsonNode node, string ns, Dictionary<string, object> parameters)
        {
            var value = node.AsObject();
            if (value["parameter"] is { } parameter)
                return parameters[(string)parameter];
            if (value["literal"] is { } literal)
                return (string)literal;
            if (value["null"] != null)
                return null;
            if (value["array"] != null)
                return value["items"].AsArray().Select(i => Evaluate(i, ns, parameters)).ToArray();
            object[] arguments = value["arguments"].AsArray().Select(a => Evaluate(a, ns, parameters)).ToArray();
            if (value["new"] is { } typeName)
            {
                Type type = ExceptionAssemblies.Select(a => a.GetType((string)typeName)).Single(t => t != null);
                Type[] parameterTypes = value["parameterTypes"].AsArray().Select(t => Type.GetType((string)t, throwOnError: true)).ToArray();
                return type.GetConstructor(parameterTypes).Invoke(arguments);
            }
            string call = (string)value["call"];
            if (call == ns + ".SR.GetString")
            {
                // .NET Framework's SR.GetString(name, args): long strings cut, then string.Format with the current culture.
                string format = Resource(ns, (string)arguments[0]);
                if (arguments.Length == 1)
                    return format;
                object[] formatArguments = ((object[])arguments[1]).Select(a => a is string s && s.Length > 1024 ? s[..1021] + "..." : a).ToArray();
                return string.Format(CultureInfo.CurrentCulture, format, formatArguments);
            }
            string memberName = call[(call.LastIndexOf('.') + 1)..].Replace("get_", "");
            JsonObject member = Member(call[..call.LastIndexOf('.')], memberName);
            var memberParameters = member["parameters"].AsArray().Select((p, i) => ((string)p["name"], arguments[i])).ToDictionary();
            return Evaluate(member["value"], ns, memberParameters);
        }

        private static string NamespaceOf(string className) => className[..className.LastIndexOf('.')];

        public class Thing
        {
        }

        [Table]
        public class TwoKeys
        {
            [Column(IsPrimaryKey = true)] public int Id { get; set; }
            [Column(IsVersion = true)] public byte[] A { get; set; }
            [Column(IsVersion = true)] public byte[] B { get; set; }
        }
    }
}
